import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.50.0";

const URL_ = Deno.env.get("SUPABASE_URL")!;
const ANON = Deno.env.get("SUPABASE_ANON_KEY")!;
const SERVICE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

const ALLOWED_ORIGINS = new Set([
  "https://math.portal.ghoneem.com",
  "https://ghoneem-exam-portal.xxx64220.chatgpt.site",
  ...(Deno.env.get("ALLOWED_ORIGIN") ?? "").split(",").map(value => value.trim()).filter(Boolean),
]);

export const cors = {
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, idempotency-key",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
  "Vary": "Origin",
};

function withCors(req: Request, response: Response): Response {
  const headers = new Headers(response.headers);
  headers.delete("Access-Control-Allow-Origin");
  for (const [name, value] of Object.entries(cors)) headers.set(name, value);
  const origin = req.headers.get("Origin");
  if (origin && ALLOWED_ORIGINS.has(origin)) headers.set("Access-Control-Allow-Origin", origin);
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

export function json(body: unknown, status = 200, extra: Record<string, string> = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...cors, ...extra, "Content-Type": "application/json" },
  });
}

export function preflight(req: Request) {
  return req.method === "OPTIONS" ? withCors(req, new Response("ok")) : null;
}

/** Service-role client. Bypasses RLS — never hand this to the browser. */
export function admin(): SupabaseClient {
  return createClient(URL_, SERVICE, { auth: { persistSession: false } });
}

export type Caller = { id: string; role: "student" | "instructor" | "admin"; status: string };

/**
 * Verifies the caller's JWT and loads their profile.
 * Throws ApiError on a missing/!invalid token or a suspended account.
 */
export async function requireUser(req: Request): Promise<Caller> {
  const auth = req.headers.get("Authorization") ?? "";
  if (!auth.startsWith("Bearer ")) throw new ApiError("missing_token", 401);

  const asUser = createClient(URL_, ANON, {
    global: { headers: { Authorization: auth } },
    auth: { persistSession: false },
  });
  const { data, error } = await asUser.auth.getUser();
  if (error || !data?.user) throw new ApiError("invalid_token", 401);

  const { data: prof, error: pe } = await admin()
    .from("profiles").select("id, role, status").eq("id", data.user.id).single();
  if (pe || !prof) throw new ApiError("no_profile", 403);
  if (prof.status !== "active") throw new ApiError("account_suspended", 403);

  const token = auth.slice(7);
  let sessionId: string;
  try { sessionId = JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).session_id; }
  catch { throw new ApiError('invalid_token',401); }
  if (!sessionId) throw new ApiError('invalid_session',401);
  const { error: se } = await admin().rpc('portal_session', {p_user:prof.id,p_session:sessionId,p_agent:req.headers.get('user-agent')||''});
  if (se) throw new ApiError(se.message,403);
  return prof as Caller;
}

export async function requireStaff(req: Request): Promise<Caller> {
  const c = await requireUser(req);
  if (c.role !== "admin" && c.role !== "instructor") throw new ApiError("forbidden", 403);
  return c;
}

export async function requireAdmin(req: Request): Promise<Caller> {
  const c = await requireUser(req);
  if (c.role !== "admin") throw new ApiError("forbidden", 403);
  return c;
}

export class ApiError extends Error {
  status: number;
  extra: Record<string, unknown>;
  constructor(msg: string, status = 400, extra: Record<string, unknown> = {}) {
    super(msg);
    this.status = status;
    this.extra = extra;
  }
}

/** Maps the exceptions raised inside the SQL layer onto HTTP status codes. */
const SQL_STATUS: Record<string, number> = {
  exam_not_found: 404,
  attempt_not_found: 404,
  exam_not_published: 403,
  not_enrolled_in_track: 403,
  not_assigned_or_window_closed: 403,
  account_suspended: 403,
  attempt_limit_reached: 403,
  already_submitted: 409,
  attempt_still_live: 409,
};

/** Extracts the bare error tag from a Postgres error surfaced by PostgREST. */
export function sqlError(e: { message?: string } | null): ApiError {
  const raw = e?.message ?? "unknown_error";
  const tag = Object.keys(SQL_STATUS).find((k) => raw.includes(k));
  return tag ? new ApiError(tag, SQL_STATUS[tag]) : new ApiError(raw, 400);
}

/** Wraps a handler so every thrown ApiError becomes a clean JSON response. */
export function serve(handler: (req: Request) => Promise<Response>) {
  return async (req: Request): Promise<Response> => {
    const pf = preflight(req);
    if (pf) return pf;
    try {
      return withCors(req, await handler(req));
    } catch (err) {
      if (err instanceof ApiError) {
        return withCors(req, json({ error: err.message, ...err.extra }, err.status));
      }
      console.error("unhandled", err);
      return withCors(req, json({ error: "internal_error" }, 500));
    }
  };
}

/** Best-effort client IP, for the attempt audit trail. */
export function clientIp(req: Request): string | null {
  const h = req.headers.get("x-forwarded-for");
  return h ? h.split(",")[0].trim() : null;
}

// POST /start-attempt  { exam_id }
// Creates the attempt (all eligibility checked inside SQL, in one transaction)
// and returns the question payload with answer keys stripped.


Deno.serve(serve(async (req) => {
  if (req.method !== "POST") throw new ApiError("method_not_allowed", 405);
  const me = await requireUser(req);
  const { exam_id, untimed } = await req.json().catch(() => ({}));
  if (!exam_id) throw new ApiError("exam_id_required", 400);

  if (me.role !== 'student') throw new ApiError('student_account_required',403);
  const db = admin();
  const {error:limit} = await db.rpc('portal_rate_limit',{p_user:me.id,p_action:'start'});
  if(limit) throw new ApiError('rate_limit_exceeded',429);

  const { data: att, error } = await db.rpc("portal_start_attempt", { p_exam: exam_id, p_user: me.id, p_untimed: untimed === true });
  if (error) throw sqlError(error);

  await db.from("attempts").update({ ip: clientIp(req), user_agent: req.headers.get("user-agent") })
    .eq("id", att.id);

  const { data: payload, error: pe } = await db.rpc("attempt_payload", {
    p_attempt: att.id, p_user: me.id,
  });
  if (pe) throw sqlError(pe);

  // Stable per-attempt ordering; original choice IDs remain authoritative for grading.
  if (payload.exam.shuffle) {
    const seed=String(payload.attempt.shuffle_seed);
    const rank=async (s:string)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(seed+s)))).map(b=>b.toString(16).padStart(2,'0')).join('');
    const qs=await Promise.all(payload.questions.map(async(q:any)=>({...q,_rank:await rank(q.id),choices:await Promise.all(q.choices.map(async(c:any)=>({...c,_rank:await rank(q.id+c.key)})))})));
    qs.sort((a,b)=>a._rank.localeCompare(b._rank));
    payload.questions=qs.map(q=>{ delete q._rank;q.choices.sort((a:any,b:any)=>a._rank.localeCompare(b._rank));q.choices.forEach((c:any)=>delete c._rank);return q;});
  }
  return json(payload, 201);
}));

